const CustomerArt = (() => {
  const urls = {};
  const rects = {"papa": [43, 6, 204, 271], "mama": [296, 11, 249, 266], "baby": [634, 129, 125, 149], "girl": [878, 34, 193, 244], "friend": [62, 338, 166, 213], "rabbit": [335, 288, 172, 264], "cat": [602, 310, 193, 242], "bear": [882, 310, 192, 242], "panda": [48, 583, 195, 239], "fox": [311, 574, 214, 249], "squirrel": [596, 583, 236, 240]};
  const image = new Image();
  const ready = new Promise(resolve => {
    image.addEventListener('load', () => {
      for (const [kind, rect] of Object.entries(rects)) {
        const canvas = document.createElement('canvas');
        canvas.width = rect[2]; canvas.height = rect[3];
        canvas.getContext('2d').drawImage(image, ...rect, 0, 0, rect[2], rect[3]);
        urls[kind] = canvas.toDataURL('image/png');
      }
      resolve();
    });
    image.addEventListener('error', () => resolve());
  });
  image.src = "data:image/webp;base64,";
  return { urls, ready };
})();
